preConditionHook:
// Plain EL Average(TrueRange, n): a FRESH mean every bar (measured 2,808/2,808,
// EL_Summation_Probe.txt) -- deliberately NOT the WFSafe_AvgTrueRange rolling
// sum. TrueRange is the two-term form max(H, C[1]) - min(L, C[1]).
fastAvg = 0.0;
for (int i = 0; i < (int)lookback; ++i) {
    double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
    double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
    fastAvg += hi - lo;
}
fastAvg /= (int)lookback;
slowLen = (int)(lookback * slowFactor);
slowAvg = 0.0;
for (int i = 0; i < slowLen; ++i) {
    double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
    double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
    slowAvg += hi - lo;
}
slowAvg /= slowLen;
